"use node";

import { action } from "./_generated/server";
import { v } from "convex/values";
import { internal } from "./_generated/api";
import { consumeRateLimit, RATE_LIMITS } from "./lib/rateLimit";
import { isProSubscription } from "./lib/entitlement";

const OPENAI_AUDIO_BASE = "https://api.openai.com/v1";
const MAX_SPEECH_CHARS = 4096;

const audioFormatValidator = v.union(
  v.literal("mp3"),
  v.literal("opus"),
  v.literal("aac"),
  v.literal("flac"),
  v.literal("wav"),
  v.literal("pcm"),
);

export const synthesizeSpeech = action({
  args: {
    text: v.string(),
    model: v.optional(v.string()),
    voice: v.optional(v.string()),
    instructions: v.optional(v.string()),
    responseFormat: v.optional(audioFormatValidator),
    speed: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Not signed in");

    // Rate limit: each synthesis is a paid OpenAI call. 20 per minute per
    // user is well above any real reading flow, and stops abuse of the
    // hosted key.
    await consumeRateLimit(ctx, {
      action: "voice:synthesize",
      identifier: identity.tokenIdentifier,
      ...RATE_LIMITS.voiceSynthesize,
    });

    const subscription = await ctx.runQuery(
      internal.payments.getSubscriptionByUserId,
      {
        userId: identity.tokenIdentifier,
      },
    );
    if (!isProSubscription(subscription)) {
      throw new Error("Voice narration is a Pro feature.");
    }

    const apiKey =
      process.env.VOICE_OPENAI_API_KEY ?? process.env.OPENAI_API_KEY;
    if (!apiKey) throw new Error("Hosted voice is not configured.");

    const input = args.text.trim().slice(0, MAX_SPEECH_CHARS);
    if (!input) throw new Error("Nothing to read.");

    const responseFormat = args.responseFormat ?? "mp3";
    const res = await fetch(`${OPENAI_AUDIO_BASE}/audio/speech`, {
      method: "POST",
      headers: {
        authorization: `Bearer ${apiKey}`,
        "content-type": "application/json",
      },
      body: JSON.stringify({
        model:
          args.model ?? process.env.VOICE_OPENAI_MODEL ?? "gpt-4o-mini-tts",
        input,
        voice: args.voice ?? process.env.VOICE_OPENAI_VOICE ?? "alloy",
        response_format: responseFormat,
        ...(args.instructions ? { instructions: args.instructions } : {}),
        ...(args.speed ? { speed: clampSpeed(args.speed) } : {}),
      }),
    });

    if (!res.ok) {
      const detail = await res.text().catch(() => "");
      throw new Error(
        `Hosted voice failed (${res.status}): ${detail.slice(0, 240)}`,
      );
    }

    return {
      audioBase64: Buffer.from(await res.arrayBuffer()).toString("base64"),
      mimeType: audioMimeType(responseFormat),
      responseFormat,
      provider: "openai",
      model: args.model ?? process.env.VOICE_OPENAI_MODEL ?? "gpt-4o-mini-tts",
      voice: args.voice ?? process.env.VOICE_OPENAI_VOICE ?? "alloy",
    };
  },
});

/** Roughly three minutes of Opus at 32kbps, base64-encoded. */
const MAX_TRANSCRIBE_BYTES = 12 * 1024 * 1024;

/**
 * Transcribe a recorded voice note.
 *
 * The mirror image of {@link synthesizeSpeech}: same identity check, same rate
 * limiter, same Pro gate, same key resolution. The audio arrives base64-encoded
 * because Convex actions take JSON — the client keeps the original Blob locally,
 * so nothing is lost by re-encoding for the wire.
 */
export const transcribeSpeech = action({
  args: {
    audioBase64: v.string(),
    mimeType: v.string(),
    /** Optional nudge for proper nouns and jargon the recording will contain. */
    prompt: v.optional(v.string()),
    model: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Not signed in");

    await consumeRateLimit(ctx, {
      action: "voice:transcribe",
      identifier: identity.tokenIdentifier,
      ...RATE_LIMITS.voiceTranscribe,
    });

    const subscription = await ctx.runQuery(
      internal.payments.getSubscriptionByUserId,
      {
        userId: identity.tokenIdentifier,
      },
    );
    if (!isProSubscription(subscription)) {
      throw new Error("Hosted transcription is a Pro feature.");
    }

    const apiKey =
      process.env.VOICE_OPENAI_API_KEY ?? process.env.OPENAI_API_KEY;
    if (!apiKey) throw new Error("Hosted transcription is not configured.");

    const bytes = Buffer.from(args.audioBase64, "base64");
    if (bytes.length === 0) throw new Error("Nothing to transcribe.");
    if (bytes.length > MAX_TRANSCRIBE_BYTES) {
      throw new Error("That recording is too long to transcribe.");
    }

    const model =
      args.model ??
      process.env.VOICE_OPENAI_TRANSCRIBE_MODEL ??
      "gpt-4o-mini-transcribe";

    const form = new FormData();
    form.append(
      "file",
      new Blob([new Uint8Array(bytes)], { type: args.mimeType }),
      `note.${extensionForMime(args.mimeType)}`,
    );
    form.append("model", model);
    form.append("response_format", "json");
    if (args.prompt?.trim()) form.append("prompt", args.prompt.trim().slice(0, 800));

    const res = await fetch(`${OPENAI_AUDIO_BASE}/audio/transcriptions`, {
      method: "POST",
      headers: { authorization: `Bearer ${apiKey}` },
      body: form,
    });

    if (!res.ok) {
      const detail = await res.text().catch(() => "");
      throw new Error(
        `Hosted transcription failed (${res.status}): ${detail.slice(0, 240)}`,
      );
    }

    const data = (await res.json()) as { text?: string };
    return {
      text: typeof data.text === "string" ? data.text.trim() : "",
      provider: "openai",
      model,
    };
  },
});

/** The file extension the transcription endpoint expects for a MIME type. */
function extensionForMime(mimeType: string): string {
  const base = mimeType.split(";")[0].trim().toLowerCase();
  switch (base) {
    case "audio/webm":
      return "webm";
    case "audio/ogg":
      return "ogg";
    case "audio/mp4":
    case "audio/m4a":
      return "m4a";
    case "audio/wav":
    case "audio/x-wav":
      return "wav";
    case "audio/mpeg":
      return "mp3";
    default:
      return "webm";
  }
}

function clampSpeed(speed: number): number {
  if (!Number.isFinite(speed)) return 1;
  return Math.max(0.25, Math.min(4, speed));
}

function audioMimeType(format: string): string {
  switch (format) {
    case "opus":
      return "audio/opus";
    case "aac":
      return "audio/aac";
    case "flac":
      return "audio/flac";
    case "wav":
      return "audio/wav";
    case "pcm":
      return "audio/L16";
    case "mp3":
    default:
      return "audio/mpeg";
  }
}

/**
 * Reading aloud — the editors get voices.
 *
 * The provider plumbing for this already existed and had no callers:
 * `runClientVoiceSpeech` (BYOK) in `ai-client.ts` and the Pro-gated
 * `voice.synthesizeSpeech` Convex action. This module is the missing middle:
 * a single-playback manager the UI can drive without every button growing its
 * own audio element and cache.
 *
 * Two decisions worth stating:
 *
 *   - **One voice at a time.** Starting a read stops whatever was playing.
 *     Five editors talking over each other is not a feature, and a stray
 *     background voice the writer cannot find the stop button for is the
 *     worst possible failure mode for an audio feature in a writing app.
 *   - **Cache by content, not by note id.** Notes are immutable once filed,
 *     but the same passage can be read from several places (the panel, the
 *     inline modal, the analysis modal). Keying on the text and voice means
 *     replaying costs nothing regardless of which button was pressed.
 */

import type { ConvexClient } from "convex/browser";
import { api } from "../../convex/_generated/api";
import type { AiProviderType, AiSettings } from "../types";
import type { AppError } from "../types/application-errors";
import {
  createAppError,
  normalizeApplicationError,
} from "./application-errors";
import {
  hasConfiguredVoiceProvider,
  resolveFeatureConfig,
  runClientVoiceSpeech,
} from "./ai-client";
import { getCachedAiSettings } from "./ai-orchestrator";

/** Cap on cached clips, so a long session doesn't hold every note in memory. */
const MAX_CACHED_CLIPS = 24;

export interface SpeakRequest {
  text: string;
  /** Stable id for the thing being read, so the UI can highlight it. */
  id: string;
  /** Fallback voice name, e.g. "onyx". */
  voice?: string;
  /**
   * Per-provider voice overrides. Providers name voices incompatibly — an
   * OpenAI name sent to Fish Audio selects nothing and every editor comes out
   * in the same default voice — so the right one is chosen once the provider
   * is known, not by the caller.
   */
  voices?: Partial<Record<AiProviderType, string>>;
  /** Voice direction — a persona's lore paragraph works well here. */
  instructions?: string;
  /** Convex client for the hosted (Pro) path. BYOK does not need it. */
  client?: ConvexClient | null;
}

export type SpeechStatus = "idle" | "loading" | "playing" | "error";

export interface SpeechState {
  status: SpeechStatus;
  /** Which `SpeakRequest.id` is active, when any. */
  id: string | null;
  error: AppError | null;
}

const state: SpeechState = { status: "idle", id: null, error: null };

let audio: HTMLAudioElement | null = null;
/** Content-addressed clip cache: `${voice}::${text}` → object URL. */
const cache = new Map<string, string>();
/** Guards against a slow request landing after the writer moved on. */
let generation = 0;

export function speechState(): SpeechState {
  return { ...state };
}

function notify(): void {
  if (typeof window === "undefined") return;
  window.dispatchEvent(
    new CustomEvent("twyne:speech", { detail: speechState() }),
  );
}

function setState(
  status: SpeechStatus,
  id: string | null,
  error: AppError | null = null,
): void {
  state.status = status;
  state.id = id;
  state.error = error;
  notify();
}

function cacheKey(text: string, voice: string): string {
  return `${voice}::${text}`;
}

function remember(key: string, url: string): void {
  cache.set(key, url);
  while (cache.size > MAX_CACHED_CLIPS) {
    const oldest = cache.keys().next().value;
    if (oldest === undefined) break;
    const stale = cache.get(oldest);
    if (stale) URL.revokeObjectURL(stale);
    cache.delete(oldest);
  }
}

/**
 * Pick the voice name for whichever provider will actually serve this request.
 * Falls back to the generic name when the provider has no specific entry, and
 * to nothing at all when there is no provider — in which case the synthesis
 * call is about to fail anyway.
 */
export function pickVoiceForProvider(
  voices: Partial<Record<AiProviderType, string>> | undefined,
  fallback: string | undefined,
  providerType: AiProviderType | undefined,
): string | undefined {
  if (providerType && voices?.[providerType]) return voices[providerType];
  return fallback;
}

function resolveVoice(req: SpeakRequest, settings: AiSettings): string | undefined {
  return pickVoiceForProvider(
    req.voices,
    req.voice,
    resolveFeatureConfig(settings, "voice-narration")?.provider.type,
  );
}

/** Stop whatever is playing. Safe to call when nothing is. */
export function stopSpeech(): void {
  generation += 1;
  if (audio) {
    audio.pause();
    audio.currentTime = 0;
  }
  setState("idle", null);
}

/**
 * Fetch the audio for a passage, BYOK first then the hosted Pro path — the
 * same order every other feature uses, so the writer's configured provider is
 * always what speaks.
 */
async function synthesize(req: SpeakRequest): Promise<Blob> {
  const text = req.text.trim();
  const settings = await getCachedAiSettings();

  // Gate on a *voice-capable* provider, not a language one: a writer may have
  // Fish Audio configured for speech and nothing else, and a writer may have
  // Anthropic configured for the room but nothing that can speak.
  if (hasConfiguredVoiceProvider(settings)) {
    const result = await runClientVoiceSpeech(
      { text, voice: resolveVoice(req, settings), instructions: req.instructions },
      settings,
    );
    if (result) return result.audio;
  }

  if (req.client) {
    const res = (await req.client.action(api.voice.synthesizeSpeech, {
      text,
      voice: req.voice,
      instructions: req.instructions,
    })) as { audioBase64: string; mimeType: string };
    const bytes = Uint8Array.from(atob(res.audioBase64), (c) =>
      c.charCodeAt(0),
    );
    return new Blob([bytes], { type: res.mimeType });
  }

  throw createAppError("CONFIGURATION_ERROR", {
    source: "application",
    recovery: { action: "choose-provider", canRetry: false },
    metadata: { feature: "voice-narration", operation: "synthesize" },
  });
}

/**
 * Read a passage aloud. Pressing the same passage again stops it (so one
 * button is both play and stop); pressing a different one switches over.
 */
export async function speak(req: SpeakRequest): Promise<void> {
  if (typeof window === "undefined") return;

  // Same passage, already sounding → this press means "stop".
  if (state.id === req.id && (state.status === "playing" || state.status === "loading")) {
    stopSpeech();
    return;
  }

  const text = req.text.trim();
  if (!text) return;

  stopSpeech();
  const mine = ++generation;
  // Key the cache on the voice that will actually be used, so two editors
  // sharing a fallback name never collide on one clip.
  const settings = await getCachedAiSettings();
  const voice = resolveVoice(req, settings) ?? req.voice ?? "alloy";
  const key = cacheKey(text, voice);

  setState("loading", req.id);

  try {
    let url = cache.get(key);
    if (!url) {
      const blob = await synthesize({ ...req, text });
      if (mine !== generation) return; // the writer moved on
      url = URL.createObjectURL(blob);
      remember(key, url);
    }
    if (mine !== generation) return;

    audio = audio ?? new Audio();
    audio.src = url;
    audio.onended = () => {
      if (mine === generation) setState("idle", null);
    };
    audio.onerror = () => {
      if (mine !== generation) return;
      setState(
        "error",
        req.id,
        createAppError("PROVIDER_ERROR", {
          source: "provider",
          metadata: { feature: "voice-narration", operation: "playback" },
        }),
      );
    };
    await audio.play();
    if (mine === generation) setState("playing", req.id);
  } catch (err) {
    if (mine !== generation) return;
    setState(
      "error",
      req.id,
      normalizeApplicationError(err, {
        source: "provider",
        metadata: { feature: "voice-narration", operation: "synthesize" },
      }),
    );
  }
}

/** Drop every cached clip and release its object URL. */
export function clearSpeechCache(): void {
  for (const url of cache.values()) URL.revokeObjectURL(url);
  cache.clear();
}

/**
 * Like {@link resolveFeatureConfig}, but lets a persona override the provider,
 * model, and temperature. This is what lets each editor run on its own model
 * so the voices differ at the generation level, not just in the prompt.
 * BYOK/client path only — the Convex hosted path uses one picked provider.
 */
export function resolveFeatureConfigForPersona(
  settings: AiSettings,
  feature: AiFeature,
  persona: { providerId?: string; model?: string; temperature?: number },
): ReturnType<typeof resolveFeatureConfig> {
  const base = resolveFeatureConfig(settings, feature);
  if (!base) return null;

  const normalized = normalizeAiSettings(settings);
  const personaProvider = persona.providerId
    ? normalized.providers.find((p) => p.id === persona.providerId)
    : undefined;
  const provider = personaProvider ?? base.provider;

  return {
    provider,
    model:
      persona.model ?? (personaProvider ? provider.defaultModel : base.model),
    temperature: persona.temperature ?? base.temperature,
    maxTokens: base.maxTokens,
  };
}

/**
 * Is there a client-side provider that can do *language* work?
 *
 * Voice-only providers are excluded deliberately. Callers use this to decide
 * whether to take the BYOK path at all, and several of them treat a BYOK
 * attempt that yields nothing as a hard error rather than falling back to the
 * server — so counting a Fish Audio key here would break the Cast panel for
 * anyone who configured voice but not an LLM.
 */
export function hasConfiguredAiProvider(
  settings: Partial<AiSettings> | AiSettings | null | undefined,
): boolean {
  if (!settings) return false;
  return normalizeAiSettings(settings).providers.some(
    (p) => !isVoiceOnlyProvider(p.type),
  );
}

/** Is there a client-side provider that can speak or listen? */
export function hasConfiguredVoiceProvider(
  settings: Partial<AiSettings> | AiSettings | null | undefined,
): boolean {
  if (!settings) return false;
  return normalizeAiSettings(settings).providers.some((p) =>
    supportsVoice(p.type),
  );
}

function defaultModelForFeature(
  feature: AiFeature,
  provider: AiProviderConfig,
): string {
  if (
    feature === "voice-narration" &&
    (provider.type === "openai" || isOpenAiCompatibleProvider(provider.type))
  ) {
    return "gpt-4o-mini-tts";
  }
  if (
    feature === "voice-transcription" &&
    (provider.type === "openai" || isOpenAiCompatibleProvider(provider.type))
  ) {
    return "gpt-4o-mini-transcribe";
  }
  if (provider.type === "fishaudio") {
    // `s2.1-pro-free` is the only model that works without API credit, so a
    // fresh key speaks straight away; transcription has no free tier.
    return feature === "voice-transcription" ? "asr-1" : "s2.1-pro-free";
  }
  return provider.defaultModel;
}

function defaultTemperature(feature: AiFeature): number {
  switch (feature) {
    case "rubric-judge":
      return 0.2;
    case "rubric-review":
      return 0.3;
    case "persona-analysis":
      return 0.5;
    case "room-synthesis":
      return 0.4;
    case "voice-narration":
    case "voice-transcription":
      return 0.4;
    case "citation-format":
      return 0.1;
    case "source-summarize":
      return 0.3;
    case "source-detect-missing":
      return 0.2;
    case "research-web-search":
      return 0.2;
    default:
      return 0.4;
  }
}

function defaultMaxTokens(feature: AiFeature): number {
  switch (feature) {
    case "persona-feedback":
      return 380;
    case "persona-reply":
      return 320;
    case "persona-rewrite":
      return 320;
    case "persona-analysis":
      return 1400;
    case "room-synthesis":
      return 1200;
    case "rubric-judge":
      return 220;
    case "rubric-review":
      return 1200;
    case "voice-narration":
    case "voice-transcription":
      return 0;
    case "comment-reply":
      return 280;
    case "citation-format":
      return 180;
    case "source-summarize":
      return 200;
    case "source-detect-missing":
      return 350;
    case "research-web-search":
      return 900;
    default:
      return 300;
  }
}

/* ── Public: generate speech client-side (BYOK) ─────────────────── */

export interface VoiceSpeechRequest {
  text: string;
  voice?: string;
  instructions?: string;
  responseFormat?: "mp3" | "opus" | "aac" | "flac" | "wav" | "pcm";
  speed?: number;
}

export interface VoiceSpeechResult {
  audio: Blob;
  provider: string;
  model: string;
  voice: string;
  responseFormat: string;
}

export async function runClientVoiceSpeech(
  req: VoiceSpeechRequest,
  settings: AiSettings,
): Promise<VoiceSpeechResult | null> {
  const resolved = resolveFeatureConfig(settings, "voice-narration");
  if (!resolved) return null;
  if (!supportsVoice(resolved.provider.type)) {
    reportApplicationDiagnostic(
      "twyne:ai-client:voice-unsupported-provider",
      createAppError("CONFIGURATION_ERROR", { source: "provider" }),
    );
    return null;
  }

  const input = req.text.trim().slice(0, 4096);
  if (!input) return null;

  const override = settings.perFeature["voice-narration"];
  const voice = req.voice ?? override?.voice ?? "alloy";
  const responseFormat =
    req.responseFormat ?? override?.responseFormat ?? "mp3";
  const speed = req.speed ?? override?.speed;
  const instructions = req.instructions ?? override?.instructions;

  if (resolved.provider.type === "fishaudio") {
    return runFishAudioSpeech({
      provider: resolved.provider,
      model: resolved.model,
      text: input,
      voice,
      responseFormat,
      speed,
    });
  }

  const baseURL =
    isOpenAiCompatibleProvider(resolved.provider.type) &&
    resolved.provider.baseUrl
      ? resolved.provider.baseUrl.replace(/\/$/, "")
      : "https://api.openai.com/v1";

  try {
    const res = await fetch(`${baseURL}/audio/speech`, {
      method: "POST",
      headers: {
        authorization: `Bearer ${resolved.provider.apiKey}`,
        "content-type": "application/json",
      },
      body: JSON.stringify({
        model: resolved.model,
        input,
        voice,
        response_format: responseFormat,
        ...(instructions ? { instructions } : {}),
        ...(speed ? { speed } : {}),
      }),
    });
    if (!res.ok) {
      const detail = await res.text().catch(() => "");
      throw new Error(
        `Voice generation failed (${res.status}): ${detail.slice(0, 240)}`,
      );
