/** Is the browser's own synthesiser available? The floor under every path. */
function hasLocalSpeech(): boolean {
  return (
    typeof window !== "undefined" &&
    "speechSynthesis" in window &&
    typeof SpeechSynthesisUtterance !== "undefined"
  );
}

/** Stop whatever is playing. Safe to call when nothing is. */
export function stopSpeech(): void {
  generation += 1;
  if (audio) {
    audio.pause();
    audio.currentTime = 0;
  }
  if (hasLocalSpeech()) window.speechSynthesis.cancel();
  setState("idle", null);
}

/**
 * Either a generated clip, or a instruction to let the browser read it.
 * The local path produces no file, so it cannot be cached or replayed like
 * the others; keeping the distinction in the type stops that from being an
 * easy mistake to make downstream.
 */
type Synthesis = { kind: "clip"; audio: Blob } | { kind: "local" };

/**
 * Get audio for a passage: BYOK, then the hosted Pro path, then the browser's
 * own synthesiser.
 *
 * The order matters, and so does what is *skipped*. The hosted action is both
 * sign-in and Pro gated; entering it without an account throws "Not signed
 * in", which is a bewildering thing to be told about a passage you asked to
 * hear on your own key. So it is only attempted when there is an account
 * behind it, and a refusal there falls through to the local voice rather than
 * ending the read.
 */
async function synthesize(req: SpeakRequest): Promise<Synthesis> {
  const text = req.text.trim();
  const settings = await getCachedAiSettings();

  // Gate on a *voice-capable* provider, not a language one: a writer may have
  // Fish Audio configured for speech and nothing else, and a writer may have
  // Anthropic configured for the room but nothing that can speak.
  if (hasConfiguredVoiceProvider(settings)) {
    const result = await runClientVoiceSpeech(
      { text, voice: resolveVoice(req, settings), instructions: req.instructions },
      settings,
    );
    if (result) return { kind: "clip", audio: result.audio };
  }

  if (req.client && req.signedIn) {
    try {
      const res = (await req.client.action(api.voice.synthesizeSpeech, {
        text,
        voice: req.voice,
        instructions: req.instructions,
      })) as { audioBase64: string; mimeType: string };
      const bytes = Uint8Array.from(atob(res.audioBase64), (c) =>
        c.charCodeAt(0),
      );
      return { kind: "clip", audio: new Blob([bytes], { type: res.mimeType }) };
    } catch (err) {
      // Not Pro, rate-limited, hosted key missing — all of them mean "the
      // hosted voice will not serve this", none of them mean the writer
      // should be left in silence.
      reportApplicationDiagnostic("twyne:speech:hosted-declined", err, {
        feature: "voice-narration",
      });
      if (!hasLocalSpeech()) throw err;
    }
  }

  if (hasLocalSpeech()) return { kind: "local" };

  throw createAppError("CONFIGURATION_ERROR", {
    source: "application",
    recovery: { action: "choose-provider", canRetry: false },
    metadata: { feature: "voice-narration", operation: "synthesize" },
  });
}

/**
 * Read a passage with the browser's own synthesiser — no key, no account, no
 * network. Plainer than a hosted voice, and the right floor for a feature
 * that should never be a paywall in a writing app.
 */
function playLocally(
  text: string,
  voice: string | undefined,
  onEnd: () => void,
  onError: () => void,
): void {
  const synth = window.speechSynthesis;
  synth.cancel();
  const utterance = new SpeechSynthesisUtterance(text);
  // Provider voice names ("onyx", a Fish voice id) mean nothing here, but a
  // writer who named a system voice should get it.
  const match = voice
    ? synth
        .getVoices()
        .find((v) => v.name.toLowerCase() === voice.toLowerCase())
    : undefined;
  if (match) utterance.voice = match;
  utterance.onend = onEnd;
  utterance.onerror = onError;
  synth.speak(utterance);
}

